@Test
    public void testPaymentsRequestWithXidAndCavv() throws Exception {
        when(client.getConfig()).thenReturn(config);
        when(config.getCheckoutEndpoint()).thenReturn("checkout");
        when(client.getHttpClient()).thenReturn(clientInterface);
        when(clientInterface.request(anyString(), anyString(), eq(config), anyBoolean(), nullable(RequestOptions.class), any())).thenReturn("{\"pspReference\": \"12345\"}");
        ArgumentCaptor<String> captor = ArgumentCaptor.forClass(String.class);
        PaymentsRequest request = new PaymentsRequest();
        ThreeDSecureData mpiData = new ThreeDSecureData();
        mpiData.setXid("AQIDBAUGBwgJCgsMDQ4PEBESExQ=");
        mpiData.setCavv("AQIDBAUGBwgJCgsMDQ4PEBESExQ=");
        request.setMpiData(mpiData);
        PaymentsResponse response = new Checkout(client).payments(request);
        assertNotNull(response);
        assertEquals("12345", response.getPspReference());
        verify(clientInterface).request(anyString(), captor.capture(), any(Config.class), anyBoolean(), nullable(RequestOptions.class), any());

assertFalse(captor.getValue().contains("\"mpiData\":{\"cavv\":\"AQIDBAUGBwgJCgsMDQ4PEBESExQ\\u003d\",\"xid\":\"AQIDBAUGBwgJCgsMDQ4PEBESExQ\\u003d\"}"));

assertTrue(captor.getValue().contains("\"mpiData\":{\"cavv\":\"AQIDBAUGBwgJCgsMDQ4PEBESExQ=\",\"xid\":\"AQIDBAUGBwgJCgsMDQ4PEBESExQ=\"}"));
    },"@Test

@Test
    public void testBuildTagSome() {
        try {
            SubscriptionData subscriptionData = FilterAPI.build(
                    "TOPIC", "A || B", ExpressionType.TAG
            );
            assertThat(subscriptionData).isNotNull();
            assertThat(subscriptionData.getTopic()).isEqualTo("TOPIC");
            assertThat(subscriptionData.getSubString()).isEqualTo("A || B");
            assertThat(ExpressionType.isTagType(subscriptionData.getExpressionType())).isTrue();

assertThat(subscriptionData.getTagsSet()).isNotNull();
            assertThat(subscriptionData.getTagsSet()).containsExactly("A", "B");
        } catch (Exception e) {
            e.printStackTrace();
            assertThat(Boolean.FALSE).isTrue();
        }
    },"@Test

@Test
  public void parameterMap_merge() throws IOException {
    Map<String, String[]> inherited = new HashMap<>();
    String[] v1 = new String[] {"v1-1", "v1-2"};
    inherited.put("p1", v1);
    Buffer buffer = Buffer.buffer("p1=v1-3;p2=v2");
    BufferInputStream inputStream = new BufferInputStream(buffer.getByteBuf());
    new Expectations() {
      {
        request.getParameterMap();
        result = inherited;
        request.getMethod();
        result = HttpMethod.PUT;
        request.getContentType();
        result = MediaType.APPLICATION_FORM_URLENCODED.toUpperCase(Locale.US) + ";abc";
        request.getInputStream();
        result = inputStream;
      }
    };

MatcherAssert.assertThat(Collections.list(requestEx.getParameterNames()), Matchers.contains("p1", "p2"));
    MatcherAssert.assertThat(requestEx.getParameterValues("p1"), Matchers.arrayContaining("v1-1", "v1-2", "v1-3"));
    Assertions.assertEquals("v1-1", requestEx.getParameter("p1"));
  },"@Test

@Test
  public void setParameter() {
    Map<String, String[]> parameterMap = new HashMap<>();
    Deencapsulation.setField(requestEx, "parameterMap", parameterMap);
    requestEx.setParameter("k1", "v1");
    requestEx.setParameter("k2", "v2");
    Assertions.assertEquals("v1", requestEx.getParameter("k1"));
    Assertions.assertEquals("v2", requestEx.getParameter("k2"));

Assertions.assertSame(parameterMap, requestEx.getParameterMap());

MatcherAssert.assertThat(Collections.list(requestEx.getParameterNames()), Matchers.contains("k1", "k2"));
  },"@Test

@Test
    public void rebalanceListener_onPartitionsAssigned() {
        long rebalanceCount = ProcessingKafkaConsumer.REBALANCE_COUNTER.count();
        TopicPartition newPartition = new TopicPartition("new-topic", 0);
        when(consumer.committed(newPartition)).thenReturn(new OffsetAndMetadata(0L));
        processingConsumer.rebalanceListener.onPartitionsAssigned(Arrays.asList(topicPartition, newPartition));
        assertThat(processingConsumer.partitions.keySet(), contains(newPartition, topicPartition));
        assertThat(ProcessingKafkaConsumer.REBALANCE_COUNTER.count(), is(rebalanceCount + 1));
    },"@Test

@Test
    public void nextRecord_manyRecords() {
        partition.load(Arrays.asList(record(1L), record(2L), record(3L)));
        assertThat(partition.hasNextRecord(), is(true));
        assertRecordsAreEqual(partition.nextRecord(), record(1L));
        assertThat(partition.pendingOffsets.keySet(), contains(1L));
        assertThat(partition.offsetPosition, is(2L));
        assertThat(partition.hasNextRecord(), is(true));
        assertRecordsAreEqual(partition.nextRecord(), record(2L));

assertThat(partition.pendingOffsets.keySet(), contains(1L, 2L));
        assertThat(partition.offsetPosition, is(3L));

assertThat(partition.hasNextRecord(), is(true));
        assertRecordsAreEqual(partition.nextRecord(), record(3L));

assertThat(partition.pendingOffsets.keySet(), contains(1L, 2L, 3L));
        assertThat(partition.offsetPosition, is(4L));

assertThat(partition.hasNextRecord(), is(false));
        assertThat(partition.nextRecord(), is(nullValue()));

assertThat(partition.pendingOffsets.keySet(), contains(1L, 2L, 3L));
        assertThat(partition.offsetPosition, is(4L));

assertThat(partition.committableOffset, is(nullValue()));
        assertThat(partition.getCommittableOffsetsSize(), is(0L));
    },"@Test

@Test
    public void nextRecord_skipPendingAndCompletedRecords() {
        partition.load(Arrays.asList(record(0L), record(1L), record(2L)));

assertRecordsAreEqual(partition.nextRecord(), record(0L));
        assertRecordsAreEqual(partition.nextRecord(), record(1L));
        assertRecordsAreEqual(partition.nextRecord(), record(2L));

assertThat(partition.hasNextRecord(), is(false));
        assertThat(partition.offsetPosition, is(3L));
        assertThat(partition.pendingOffsets.keySet(), contains(0L, 1L, 2L));
        assertThat(partition.completedOffsets, empty());

assertThat(partition.ack(0L), is(true));

assertThat(partition.pendingOffsets.keySet(), contains(1L, 2L));
        assertThat(partition.completedOffsets, contains(0L));

assertThat(partition.committableOffset, is(1L));
        assertThat(partition.lastCommittedOffset, is(0L));
        assertThat(partition.getCommittableOffsetsSize(), is(1L));

assertThat(partition.fail(2L), is(true));
        assertThat(partition.pendingOffsets.keySet(), contains(1L));
        assertThat(partition.completedOffsets, contains(0L));
        assertThat(partition.committableOffset, is(1L));
        assertThat(partition.lastCommittedOffset, is(0L));
        assertThat(partition.getCommittableOffsetsSize(), is(1L));
        verify(consumer).seek(topicPartition, 0L);
        assertThat(partition.offsetPosition, is(0L));

partition.load(Arrays.asList(record(0L), record(1L), record(2L)));

assertRecordsAreEqual(partition.nextRecord(), record(2L));

assertThat(partition.hasNextRecord(), is(false));
        assertThat(partition.offsetPosition, is(3L));
        assertThat(partition.pendingOffsets.keySet(), contains(1L, 2L));
        assertThat(partition.completedOffsets, contains(0L));

assertThat(partition.committableOffset, is(1L));
        assertThat(partition.lastCommittedOffset, is(0L));
        assertThat(partition.getCommittableOffsetsSize(), is(1L));
    },"@Test

@Test
    public void shouldAddItemsWithDeduplicate() {

final boolean deduplicate = true;
        final OneOrMore<Integer> collection = new OneOrMore<>(deduplicate);
        final Set<Integer> expectedItems = new HashSet<>();
        IntStream.rangeClosed(1, 200).forEach(expectedItems::add);

for (int i = 200; 0 < i; i--) {
            collection.add(i);
            collection.add(i);
        }

assertThat(collection).containsExactlyElementsOf(expectedItems);
    },"@Test

